// clang-format on

// Vertical chrome section, top to bottom: bright crown, falloff into a dark band, a
// hard highlight where the horizon reflects, falloff again, bounce light off the
// surface the letters stand on. This one table is what makes the wordmark look like
// polished metal instead of a stencil.
static const uint8_t chromeRamp[LogoPainter::CapHeight] = {
    13, 15, 15, 14, 12, 10,  9,  8,  7,  6,  5,
     4,  4, 15, 14, 12, 11, 10,  9,  8,  9, 12,
};

// How the mirrored reflection fades away from the baseline, in sixteenths.
static const uint8_t reflectionFade[LogoPainter::ReflectionRows] = { 9, 6, 5, 4, 3, 2 };

static const int Tracking = 2;      // gap between letters
static const int WordSpace = 12;    // gap between words
static const int SweepRadius = 14;  // half-width of the specular band, in pixels
static const int SweepGain = 7;     // how much brightness it adds at its centre

static const int TinyGlyphWidth = 5;

static int glyphIndex(char c) {
    const char *p = std::strchr(glyphOrder, c);
    return (p && c != '\0') ? int(p - glyphOrder) : -1;
}

int LogoPainter::wordmarkWidth(const char *text) {
    int width = 0;
    for (const char *c = text; *c; ++c) {
        if (*c == ' ') {
            width += WordSpace;
            continue;
        }
        int index = glyphIndex(*c);
        if (index >= 0) {
            width += glyphs[index].width + Tracking;
        }
    }
    return width > 0 ? width - Tracking : 0;
}

void LogoPainter::drawWordmark(Canvas &canvas, int x, int y, const char *text, float sweep) {
    int total = wordmarkWidth(text);
    if (total <= 0) {
        return;
    }

    // Precompute the specular contribution per column once, then the inner loop is a
    // table lookup. The band starts and ends fully off the wordmark so it never parks
    // on a letter.
    uint8_t boost[CONFIG_LCD_WIDTH];
    int columns = std::min(total, int(sizeof(boost)));
    float center = -SweepRadius + sweep * (total + 2 * SweepRadius);
    for (int i = 0; i < columns; ++i) {
        float d = std::abs(i - center);
        boost[i] = d < SweepRadius ? uint8_t((SweepRadius - d) * SweepGain / SweepRadius) : 0;
    }

    int cx = 0;
    for (const char *c = text; *c; ++c) {
        if (*c == ' ') {
            cx += WordSpace;
            continue;
        }
        int index = glyphIndex(*c);
        if (index < 0) {
            continue;
        }
        const LogoGlyph &glyph = glyphs[index];
        for (int row = 0; row < CapHeight; ++row) {
            uint32_t bits = glyph.rows[row];
            if (bits == 0) {
                continue;
            }
            int base = chromeRamp[row];
            for (int col = 0; col < glyph.width; ++col) {
                if (bits & (uint32_t(1) << (glyph.width - 1 - col))) {
                    int lx = cx + col;
                    int value = base + (lx < columns ? boost[lx] : 0);
                    canvas.setColorValue(std::min(15, value));
                    canvas.point(x + lx, y + row);
                }
            }
        }
        cx += glyph.width + Tracking;
    }
}

void LogoPainter::drawReflection(Canvas &canvas, int x, int y, const char *text) {
    int cx = 0;
    for (const char *c = text; *c; ++c) {
        if (*c == ' ') {
            cx += WordSpace;
            continue;
        }
        int index = glyphIndex(*c);
        if (index < 0) {
            continue;
        }
        const LogoGlyph &glyph = glyphs[index];
        // Mirrored about the baseline, so the row just below it is the bottom of the
        // letter, and it fades out fast.
        for (int k = 0; k < ReflectionRows; ++k) {
            int row = CapHeight - 1 - k;
            uint32_t bits = glyph.rows[row];
            if (bits == 0) {
                continue;
            }
            int value = (chromeRamp[row] * reflectionFade[k]) / 16;
            if (value <= 0) {
                continue;
            }
            canvas.setColorValue(uint8_t(value));
            for (int col = 0; col < glyph.width; ++col) {
                if (bits & (uint32_t(1) << (glyph.width - 1 - col))) {
                    canvas.point(x + cx + col, y + k);
                }
            }
        }
        cx += glyph.width + Tracking;
    }
}

void LogoPainter::drawTrackedText(Canvas &canvas, int x, int y, const char *text, int pitch) {
    char glyph[2] = { 0, 0 };
    for (int i = 0; text[i]; ++i) {
        glyph[0] = text[i];
        canvas.drawText(x + i * pitch, y, glyph);
    }
}

int LogoPainter::trackedTextWidth(const char *text, int pitch) {
    int len = int(std::strlen(text));
    return len > 0 ? (len - 1) * pitch + TinyGlyphWidth : 0;
}

int LogoPainter::drawPerformerMark(Canvas &canvas, int x, int y) {
    const int pitch = 7;
    canvas.setFont(Font::Tiny);

    canvas.setColor(Color::MediumBright);
    drawTrackedText(canvas, x, y, "PER", pitch);
    int barX = x + 3 * pitch - 1;

    // The divider is the mark. It is the brightest thing on the line.
    canvas.setColor(Color::Bright);
    canvas.fillRect(barX, y - 6, 2, 7);

    canvas.setColor(Color::MediumBright);
    int tailX = barX + 5;
    drawTrackedText(canvas, tailX, y, "FORMER", pitch);

    return tailX + trackedTextWidth("FORMER", pitch) - x;
}
